-- Fee ledger (docs/designs/fee-ledger): one balanced journal per receipt at commit and one reversal per cancellation, written
-- only by two definer trigger functions; the chart of accounts; fee types mapped to accounts. Head generated by prisma migrate diff.
-- AlterTable
ALTER TABLE "app"."fee_type" ADD COLUMN     "account_id" INTEGER;

-- CreateTable
CREATE TABLE "app"."account" (
    "id" SERIAL NOT NULL,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "kind" TEXT NOT NULL,
    "system_key" TEXT,
    "active" BOOLEAN NOT NULL DEFAULT true,

    CONSTRAINT "account_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "app"."journal_entry" (
    "id" BIGSERIAL NOT NULL,
    "centre_id" INTEGER NOT NULL,
    "entry_date" DATE NOT NULL,
    "currency" CHAR(3) NOT NULL,
    "source" TEXT NOT NULL,
    "receipt_id" BIGINT NOT NULL,
    "reversal_of" BIGINT,
    "reference" TEXT NOT NULL,
    "narration" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "journal_entry_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "app"."journal_line" (
    "id" BIGSERIAL NOT NULL,
    "entry_id" BIGINT NOT NULL,
    "centre_id" INTEGER NOT NULL,
    "account_id" INTEGER NOT NULL,
    "debit" DECIMAL(14,2) NOT NULL,
    "credit" DECIMAL(14,2) NOT NULL,

    CONSTRAINT "journal_line_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "account_code_key" ON "app"."account"("code");

-- CreateIndex
CREATE UNIQUE INDEX "account_system_key_key" ON "app"."account"("system_key");

-- CreateIndex
CREATE INDEX "journal_entry_centre_id_entry_date_idx" ON "app"."journal_entry"("centre_id", "entry_date");

-- CreateIndex
CREATE UNIQUE INDEX "journal_entry_id_centre_id_key" ON "app"."journal_entry"("id", "centre_id");

-- CreateIndex
CREATE UNIQUE INDEX "journal_entry_receipt_id_source_key" ON "app"."journal_entry"("receipt_id", "source");

-- CreateIndex
CREATE INDEX "journal_line_entry_id_idx" ON "app"."journal_line"("entry_id");

-- AddForeignKey
ALTER TABLE "app"."fee_type" ADD CONSTRAINT "fee_type_account_id_fkey" FOREIGN KEY ("account_id") REFERENCES "app"."account"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "app"."journal_entry" ADD CONSTRAINT "journal_entry_centre_id_fkey" FOREIGN KEY ("centre_id") REFERENCES "app"."centre"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "app"."journal_entry" ADD CONSTRAINT "journal_entry_receipt_id_centre_id_fkey" FOREIGN KEY ("receipt_id", "centre_id") REFERENCES "app"."receipt"("id", "centre_id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "app"."journal_entry" ADD CONSTRAINT "journal_entry_reversal_of_fkey" FOREIGN KEY ("reversal_of") REFERENCES "app"."journal_entry"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "app"."journal_line" ADD CONSTRAINT "journal_line_entry_id_centre_id_fkey" FOREIGN KEY ("entry_id", "centre_id") REFERENCES "app"."journal_entry"("id", "centre_id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "app"."journal_line" ADD CONSTRAINT "journal_line_account_id_fkey" FOREIGN KEY ("account_id") REFERENCES "app"."account"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;



-- ---------- Named checks ----------
alter table app.account add constraint account_kind_check check (kind in ('ASSET', 'LIABILITY', 'INCOME', 'EXPENSE'));
alter table app.journal_entry add constraint journal_entry_source_check check (source in ('RECEIPT', 'RECEIPT_CANCEL')
  and ((source = 'RECEIPT_CANCEL') = (reversal_of is not null)));
alter table app.journal_entry add constraint journal_entry_currency_check check (currency ~ '^[A-Z]{3}$');
alter table app.journal_line add constraint journal_line_amount_check check (debit >= 0 and credit >= 0 and ((debit > 0) <> (credit > 0)));

