-- ---------- A fee type posts to an active income or liability head, never a system (cash, bank, tax) account (DD-7, PMC);
-- null = not yet mapped ----------
create function app.fee_type_account_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
begin
  if new.account_id is not null then
    perform 1 from app.account a where a.id = new.account_id and a.active and a.kind in ('INCOME', 'LIABILITY') and a.system_key is null;
    if not found then
      raise exception 'a fee type posts to an active income or liability account: constraint "fee_type_account_guard"' using errcode = '23514', constraint = 'fee_type_account_guard';
    end if;
  end if;
  return new;
end $$;
create trigger fee_type_account_guard before insert or update of account_id on app.fee_type for each row execute function app.fee_type_account_guard();

-- ---------- Posting: two definer trigger functions, the only writers of journals (DD-1). Owned by the migration role, which
-- bypasses RLS (T-RLS-005); never callable (revoked, and trigger functions cannot be called). Every name qualified. ----------
create function app.receipt_post_journal() returns trigger
language plpgsql security definer set search_path = pg_catalog, app, pg_temp
as $$
declare
  r record; e bigint; dr numeric; cr numeric; n int; bad int;
begin
  select x.id, x.centre_id, x.received_on, x.currency::text as currency, x.mode, x.total, x.receipt_no, x.status
    into r from app.receipt x where x.id = new.id;
  if not found or r.status is distinct from 'ACTIVE' then
    raise exception 'a journal is posted for an active receipt: constraint "journal_balance_guard"' using errcode = '23514', constraint = 'journal_balance_guard';
  end if;
  -- every line's fee type maps to an active income or liability account
  select count(*) into bad from app.receipt_allocation l join app.fee_due d on d.id = l.due_id join app.fee_type t on t.id = d.fee_type_id
    left join app.account a on a.id = t.account_id
   where l.receipt_id = r.id and (a.id is null or not a.active or a.kind not in ('INCOME', 'LIABILITY') or a.system_key is not null);
  if bad > 0 then
    raise exception 'a fee type on this receipt has no ledger account: constraint "journal_account_guard"' using errcode = '23514', constraint = 'journal_account_guard';
  end if;
  insert into app.journal_entry (centre_id, entry_date, currency, source, receipt_id, reference, narration)
    values (r.centre_id, r.received_on, r.currency, 'RECEIPT', r.id, r.receipt_no, 'Receipt ' || r.receipt_no)
    returning id into e;
  -- the debit first: the mode's account (DD-3; R-035 swaps in the receipt's bank here)
  insert into app.journal_line (entry_id, centre_id, account_id, debit, credit)
    select e, r.centre_id, a.id, r.total, 0 from app.account a where a.system_key = case when r.mode = 'CASH' then 'CASH' else 'BANK' end;
  -- credits: taxable per account, by account code; then CGST, SGST, IGST; only sums above 0 (DD-8: no Round Off)
  insert into app.journal_line (entry_id, centre_id, account_id, debit, credit)
    select e, r.centre_id, s.account_id, 0, s.amt from (
      select t.account_id, a.code, sum(l.taxable) as amt
        from app.receipt_allocation l join app.fee_due d on d.id = l.due_id join app.fee_type t on t.id = d.fee_type_id
        join app.account a on a.id = t.account_id
       where l.receipt_id = r.id group by t.account_id, a.code) s
     where s.amt > 0 order by s.code;
  insert into app.journal_line (entry_id, centre_id, account_id, debit, credit)
    select e, r.centre_id, a.id, 0, x.amt from (
      select 'CGST' as k, 1 as o, sum(cgst) as amt from app.receipt_allocation where receipt_id = r.id
      union all select 'SGST', 2, sum(sgst) from app.receipt_allocation where receipt_id = r.id
      union all select 'IGST', 3, sum(igst) from app.receipt_allocation where receipt_id = r.id) x
      join app.account a on a.system_key = x.k
     where x.amt > 0 order by x.o;
  select count(*), coalesce(sum(debit), 0), coalesce(sum(credit), 0) into n, dr, cr from app.journal_line where entry_id = e;
  if n < 2 or dr is distinct from r.total or cr is distinct from r.total then
    raise exception 'a journal balances to its receipt: constraint "journal_balance_guard"' using errcode = '23514', constraint = 'journal_balance_guard';
  end if;
  return null;
end $$;
revoke all on function app.receipt_post_journal() from public;
-- after receipt_total_commit by name, so the total check fires first at commit (Z2, C1)
create constraint trigger receipt_zpost after insert on app.receipt deferrable initially deferred
  for each row execute function app.receipt_post_journal();

create function app.receipt_post_reversal() returns trigger
language plpgsql security definer set search_path = pg_catalog, app, pg_temp
as $$
declare o record; e bigint;
begin
  select j.id, j.currency::text as currency into o from app.journal_entry j where j.receipt_id = new.id and j.source = 'RECEIPT';
  if not found then
    raise exception 'a cancellation reverses a posted receipt: constraint "journal_reversal_guard"' using errcode = '23514', constraint = 'journal_reversal_guard';
  end if;
  -- the date is chosen here only (F12 adds its open-period rule here; a later-period reversal is a credit-note question, D10)
  insert into app.journal_entry (centre_id, entry_date, currency, source, receipt_id, reversal_of, reference, narration)
    values (new.centre_id, (new.cancelled_at at time zone 'Asia/Kolkata')::date, o.currency, 'RECEIPT_CANCEL', new.id, o.id,
      new.receipt_no, 'Reversal of ' || new.receipt_no)
    returning id into e;
  -- the original's own lines, debit and credit swapped (D3): a later re-mapping never changes a reversal
  insert into app.journal_line (entry_id, centre_id, account_id, debit, credit)
    select e, l.centre_id, l.account_id, l.credit, l.debit from app.journal_line l where l.entry_id = o.id order by l.id;
  return null;
end $$;
revoke all on function app.receipt_post_reversal() from public;
create trigger receipt_post_cancel after update of status on app.receipt for each row
  when (old.status = 'ACTIVE' and new.status = 'CANCELLED') execute function app.receipt_post_reversal();

-- ---------- Never changed ----------
create trigger journal_entry_no_update_delete before update or delete on app.journal_entry for each row execute function app.ticket_immutable();
create trigger journal_entry_no_truncate before truncate on app.journal_entry for each statement execute function app.ticket_immutable();
create trigger journal_line_no_update_delete before update or delete on app.journal_line for each row execute function app.ticket_immutable();
create trigger journal_line_no_truncate before truncate on app.journal_line for each statement execute function app.ticket_immutable();

-- ---------- RLS: the chart for all; journals by ledger.view at their centre; no writes by anyone but the definers ----------
alter table app.account enable row level security;
alter table app.account force row level security;
create policy account_select on app.account for select using (true);
do $$
declare t text;
begin
  foreach t in array array['journal_entry', 'journal_line'] loop
    execute format('alter table app.%I enable row level security', t);
    execute format('alter table app.%I force row level security', t);
    execute format('create policy %I on app.%I for select using (centre_id = any ((select app.scoped_centre_ids(''ledger.view''))::int[]))', t || '_select', t);
    execute format('create policy %I on app.%I for insert with check (false)', t || '_insert', t);
    execute format('create policy %I on app.%I for update using (false)', t || '_update', t);
    execute format('create policy %I on app.%I for delete using (false)', t || '_delete', t);
  end loop;
end $$;

-- ---------- Permission ----------
insert into app.permission (key, description, sensitive) values ('ledger.view', 'View the ledger (day book) of a centre', false)
on conflict (key) do nothing;
insert into app.role_permission (role_id, permission_key) select id, 'ledger.view' from app.role where key = 'system_admin'
on conflict do nothing;

-- ---------- Grants: read only; fee setup maps a fee type's account ----------
grant select on app.account, app.journal_entry, app.journal_line to gems_app;
grant insert (account_id), update (account_id) on app.fee_type to gems_app;
